import pytest


@pytest.mark.parametrize(
    "petId, additionalMetadata, file_path, expected_status, expected_response_contains",
    [
        (123, "example metadata", "test_image.jpg", 200, ["code", "type", "message"]),
        (999, None, None, 400, ["No file uploaded"]),
        (0, None, "test_image.jpg", 404, ["Pet not found"]),
    ],
)
def test_upload_pet_image_valid(
    petId, additionalMetadata, file_path, expected_status, expected_response_contains, api_helper, valid_api_key, oauth2_token, schema_validator
):
    """Test /pet/{petId}/uploadImage endpoint with valid cases and assertions."""
    files = {"file": open(file_path, "rb")}
    params = {"additionalMetadata": additionalMetadata} if additionalMetadata else {}
    url = f"pet/{petId}/uploadImage"
    headers = {"Authorization": f"Bearer {oauth2_token}"}

    try:
        response = api_helper.make_request(endpoint=url, params=params, headers=headers, method="POST")
        assert response.status_code == expected_status

        if expected_status == 200:
            response_json = response.json()
            assert schema_validator.validate_schema_api_response(response_json)
            assert all(field in response_json for field in expected_response_contains)
        else:
            assert expected_response_contains[0] in response.text

    finally:
        if file_path and files["file"]:
            files["file"].close()


